		records = parse(text, {
			bom: true,
			columns: false,
			cast: false,
			trim: false,
			delimiter: ",",
			quote: '"',
			escape: '"',
			record_delimiter: ["\r\n", "\n"],
			max_record_size: 262144,
			skip_empty_lines: false,
		});
	} catch {
		throw new TransferError("invalid-format");
	}
	if (
		!records.length ||
		records[0].length !== columns.length ||
		records[0].some((c, i) => c !== columns[i])
	)
		throw new TransferError("invalid-format");
	if (records.length - 1 > config.maxRows)
		throw new TransferError("limit-exceeded");
	const rows: T[] = [];
	const issues: ValidationIssue[] = [];
	let count = 0;
	let normalized = 0;
	let outputNormalized = 0;
	for (let i = 1; i < records.length; i++) {
		const record = records[i];
		if (
			record.length !== columns.length ||
			(record.length === 1 && record[0] === "")
		)
			throw new TransferError("invalid-format");
		const input = Object.create(null) as Record<string, string>;
		columns.forEach((c, j) => {
			input[c] = record[j];
		});
		normalized += Buffer.byteLength(JSON.stringify(input));
		if (normalized > config.maxBytes * 2)
			throw new TransferError("limit-exceeded");
		const result = schema.safeParse(input);
		if (result.success) {
			const encoded = JSON.stringify(result.data);
			if (encoded === undefined) throw new TransferError("unsupported");
			outputNormalized += Buffer.byteLength(encoded);
			if (outputNormalized > config.maxBytes * 2)
				throw new TransferError("limit-exceeded");
			rows.push(result.data);
		} else
			for (const issue of result.error.issues) {
				count++;
				if (issues.length < 100) {
					const field =
						typeof issue.path[0] === "string" && columns.includes(issue.path[0])
							? issue.path[0]
							: undefined;
					issues.push({
						row: i,
						...(field ? { field } : {}),
						code: "invalid-value",
